#!/usr/bin/env python3
"""Generate the C entry table for one grouped test runner.

Each grouped test source is compiled with ``-Dmain=<name>_main``; this table
maps the test name to that entry point.  The runner executes exactly one test
per process so production statics never leak from one test into the next.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

NAME = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def render(names: list[str]) -> str:
    lines = [
        "/* Generated by scripts/gen_test_registry.py. Do not edit. */",
        "#include <stdio.h>",
        "#include <string.h>",
        "",
    ]
    lines += [f"int {name}_main(void);" for name in names]
    lines += [
        "",
        "static const struct {",
        "    const char *name;",
        "    int (*run)(void);",
        "} tests[] = {",
    ]
    lines += [f'    {{"{name}", {name}_main}},' for name in names]
    lines += [
        "};",
        "",
        "int main(int argc, char **argv)",
        "{",
        "    size_t i;",
        "",
        "    if (argc == 2 && strcmp(argv[1], \"--list\") == 0) {",
        "        for (i = 0; i < sizeof(tests) / sizeof(tests[0]); i++)",
        "            puts(tests[i].name);",
        "        return 0;",
        "    }",
        "    if (argc != 2) {",
        "        fprintf(stderr, \"usage: %s --list | TEST\\n\", argv[0]);",
        "        return 2;",
        "    }",
        "    for (i = 0; i < sizeof(tests) / sizeof(tests[0]); i++) {",
        "        if (strcmp(argv[1], tests[i].name) == 0)",
        "            return tests[i].run();",
        "    }",
        "    fprintf(stderr, \"unknown test: %s\\n\", argv[1]);",
        "    return 2;",
        "}",
        "",
    ]
    return "\n".join(lines)


def main(argv: list[str]) -> int:
    if len(argv) < 2:
        print("usage: gen_test_registry.py OUTPUT TEST...", file=sys.stderr)
        return 2
    output = Path(argv[0])
    names = argv[1:]
    invalid = [name for name in names if not NAME.fullmatch(name)]
    if invalid:
        print("gen_test_registry: invalid test names: " + " ".join(invalid),
              file=sys.stderr)
        return 2
    duplicates = sorted({name for name in names if names.count(name) > 1})
    if duplicates:
        print("gen_test_registry: duplicate test names: " + " ".join(duplicates),
              file=sys.stderr)
        return 2
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open("w", encoding="utf-8", newline="\n") as generated:
        generated.write(render(names))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
